INSERT INTO `announcements` (`id`, `school_id`, `title`, `body`, `author_id`, `audience`, `status`, `published_at`, `created_at`, `updated_at`) VALUES
	(1, 1, 'Inicio de gestión escolar 2026', 'Damos la bienvenida a toda la comunidad educativa al nuevo año escolar. Las clases inician con normalidad en ambos turnos.', 2, 'todos', 'publicado', '2026-06-12 14:17:46', '2026-06-23 14:17:46', '2026-06-23 14:17:46'),
	(2, 1, 'Reunión de padres de familia', 'Se convoca a los padres de familia a la primera reunión general el próximo viernes a horas 18:00 en el salón auditorio.', 2, 'padres', 'publicado', '2026-06-03 14:17:46', '2026-06-23 14:17:46', '2026-06-23 14:17:46'),
	(3, 1, 'Entrega de notas del primer trimestre', 'Los boletines del primer trimestre estarán disponibles a partir de la próxima semana. Agradecemos su puntualidad.', 2, 'estudiantes', 'publicado', '2026-06-16 14:17:46', '2026-06-23 14:17:46', '2026-06-23 14:17:46'),
	(4, 1, 'Capacitación docente', 'Recordamos a todo el plantel docente la jornada de capacitación pedagógica programada para el sábado.', 2, 'docentes', 'publicado', '2026-06-16 14:17:46', '2026-06-23 14:17:46', '2026-06-23 14:17:46'),
	(5, 1, 'Comunicado 1: Recordatorio', 'Estimada comunidad educativa, les informamos sobre las actividades programadas. Agradecemos su atención.', 2, 'estudiantes', 'publicado', '2026-05-15 01:55:17', '2026-05-15 01:55:17', '2026-05-15 01:55:17'),
	(6, 1, 'Comunicado 2: Recordatorio', 'Estimada comunidad educativa, les informamos sobre las actividades programadas. Agradecemos su atención.', 2, 'todos', 'publicado', '2026-05-19 01:55:17', '2026-05-19 01:55:17', '2026-05-19 01:55:17'),
